-- V33's self-referencing copy-then-null approach was not stable across
-- SchemaRepairRunner's repeated startup replays: on Render's free tier the
-- app restarts periodically, and each restart re-runs every migration file.
-- A statement that copies one row's image into another and then nulls the
-- source depends on exact execution order holding across restarts, which
-- it did not - both the real products and the donor posts ended up with no
-- image at all instead of the intended fix.
--
-- Replaces that with unconditional, order-independent UPDATEs that embed
-- the correct image directly as a literal base64 data URI, matching the
-- pattern already used for reliable, network-independent image storage
-- elsewhere in this app. Idempotent: only fills in rows that are still
-- missing an image, so it never overwrites a manually-set photo later.

UPDATE marketplace_posts
SET image_url = 'data:image/jpeg;base64,'
WHERE title = 'Cassava' AND domain = 'farm' AND image_url IS NULL;

UPDATE product_batches pb
SET image_url = mp.image_url
FROM marketplace_posts mp
WHERE mp.product_batch_id = pb.id
  AND mp.title = 'Cassava' AND mp.domain = 'farm'
  AND mp.image_url IS NOT NULL AND pb.image_url IS NULL;

UPDATE marketplace_posts
SET image_url = 'data:image/jpeg;base64,'
WHERE title = 'Pineapple' AND domain = 'farm' AND image_url IS NULL;

UPDATE product_batches pb
SET image_url = mp.image_url
FROM marketplace_posts mp
WHERE mp.product_batch_id = pb.id
  AND mp.title = 'Pineapple' AND mp.domain = 'farm'
  AND mp.image_url IS NOT NULL AND pb.image_url IS NULL;

UPDATE marketplace_posts
SET image_url = NULL
WHERE title IN ('Test Cassava Batch', 'Alvaro Pineapple Drink');

UPDATE product_batches pb
SET image_url = NULL
FROM marketplace_posts mp
WHERE mp.product_batch_id = pb.id
  AND mp.title IN ('Test Cassava Batch', 'Alvaro Pineapple Drink');
